def transform(g):
    h,w=len(g),len(g[0])
    row0=g[0]
    p=None
    for q in range(1,w):
        if all(row0[j]==row0[j+q] for j in range(w-q) if row0[j]!=0 and row0[j+q]!=0):
            p=q; break
    # vote for D values
    from collections import defaultdict
    votes=defaultdict(lambda: defaultdict(int))
    for i in range(h):
        for j in range(w):
            v=g[i][j]
            if v:
                votes[(j+1) if j<i else j][v]+=1
    D={}
    for k,vv in votes.items(): D[k]=max(vv,key=vv.get)
    def Dv(k): return D[k%p]
    return [[Dv(j+1) if j<i else Dv(j) for j in range(w)] for i in range(h)]

